INSERT INTO contenidos(id,contenido) VALUES('C04','Regularidades y Patrones.');
INSERT INTO contenidos(id,contenido) VALUES('C05','Introducción al álgebra.');
INSERT INTO contenidos(id,contenido) VALUES('C06','Ecuaciones lineales y cuadráticas.');
INSERT INTO contenidos(id,contenido) VALUES('C07','Funciones.');
INSERT INTO contenidos(id,contenido) VALUES('C08','Rectas y ángulos.');
INSERT INTO contenidos(id,contenido) VALUES('C09','Construcción y propiedades de las figuras planas y cuerpos.');
INSERT INTO contenidos(id,contenido) VALUES('C10','Circunferencia, círculo y esfera.');
INSERT INTO contenidos(id,contenido) VALUES('C11','Medición y cálculo en diferentes contextos.');
INSERT INTO contenidos(id,contenido) VALUES('C12','Obtención y representación de información.');
