INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C09-P01','C09',1,'Utiliza la regla y el compás para trazar: punto medio, mediatriz de un segmento, segmentos y ángulos congruentes, bisectriz de un ángulo, rectas perpendiculares y rectas paralelas.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C09-P02','C09',1,'Identifica y traza las rectas notables en triángulos y cuadriláteros.');
