INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C09-P04','C09',2,'Construye con regla y compás polígonos regulares con distinta información.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C09-P05','C09',2,'Identifica y usa las relaciones entre figuras en la construcción de teselados.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C09-P06','C09',3,'Aplica las propiedades de la congruencia y semejanza de triángulos al construir y resolver problemas.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C09-P07','C09',3,'Reconoce las propiedades de los sólidos.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C09-P08','C09',3,'Explora la generación de sólidos de revolución a partir de figuras planas.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C09-P09','C09',3,'Explora y construye desarrollos planos de diferentes figuras tridimensionales, cilindros, pirámides y conos.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C10-P01','C10',1,'Identifica y traza las rectas notables en la circunferencia y las relaciones entre ellas.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C10-P02','C10',1,'Investiga figuras relacionadas con círculos y propiedades de los círculos.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C10-P03','C10',1,'Construye circunferencias a partir de distinta información. Verifica los criterios de existencia y unicidad de estas figuras.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C10-P04','C10',2,'Explora las intersecciones entre círculos y figuras al calcular perímetros y áreas.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C10-P05','C10',3,'Explora y construye desarrollos planos de esferas.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C10-P06','C10',3,'Indaga la generación de esferas a partir de figuras planas.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C10-P07','C10',3,'Encuentra relaciones de volumen de la esfera, el cono y el cilindro.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C11-P01','C11',1,'Introduce la idea de distancia entre dos puntos como la longitud del segmento que los une.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C11-P02','C11',1,'Encuentra la distancia de un punto a una recta y la distancia entre dos rectas paralelas.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C11-P03','C11',1,'Explora la desigualdad del triángulo.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C11-P04','C11',1,'Obtiene y aplica fórmulas o usa otras estrategias para calcular el perímetro y el área de polígonos regulares e irregulares y del círculo.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C11-P05','C11',2,'Resuelve problemas que implican conversiones en múltiplos y submúltiplos del metro, litro, kilogramo y de unidades del sistema inglés (yarda, pulgada, galón, onza y libra).');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C11-P06','C11',2,'Utiliza estrategias diversas para determinar el perímetro y el área de figuras compuestas.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C11-P07','C11',3,'Usa diferentes estrategias para calcular el volumen de prismas, pirámides y cilindros.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C11-P08','C11',3,'Formula, justifica y usa el teorema de Pitágoras al resolver problemas.');
INSERT INTO pdas(id,contenido_id,grado,pda) VALUES('C11-P09','C11',3,'Resuelve problemas utilizando las razones trigonométricas seno, coseno y tangente.');
