INSERT INTO problemas(id,contenido_id,referencia,tipo,numero,fuente,texto,figura,motivo_sin_clasificar,ubicacion) VALUES('PR-0777','C09','Problema 71 (Introductorio 21 (2007))','Problema','71','Introductorio 21 (2007)','En la figura ABCD y DBEF son rectángulos. ¿Cuál es el área de DBEF? [figura en el PDF original; en la figura aparecen 3 cm y 4 cm] a) 10 cm² b) 12 cm² c) 13 cm² d) 14 cm² e) 16 cm²','Marcada en original',NULL,'Tabla 1, fila 10');
