INSERT INTO problemas(id,contenido_id,referencia,tipo,numero,fuente,texto,figura,motivo_sin_clasificar,ubicacion) VALUES('PR-1261','C14','Problema 28 (Introductorio 20 (2006))','Problema','28','Introductorio 20 (2006)','Pablito recorta cada una de las cifras del número 2003 de un periódico, y se dispone a pegar algunos de estos cuatro trocitos de papel (o tal vez todos) en un renglón de su cuaderno para formar un número. ¿Cuántos números distintos puede construir de esta manera? a) 12 b) 15 c) 18 d) 19 e) 21','Sin alerta automática',NULL,'Tabla 1, fila 15');
