PRAGMA foreign_keys=ON;
BEGIN TRANSACTION;
CREATE TABLE contenidos(id TEXT PRIMARY KEY, contenido TEXT NOT NULL UNIQUE);
CREATE TABLE pdas(id TEXT PRIMARY KEY, contenido_id TEXT NOT NULL REFERENCES contenidos(id), grado INTEGER NOT NULL CHECK(grado BETWEEN 1 AND 3), pda TEXT NOT NULL);
CREATE TABLE problemas(id TEXT PRIMARY KEY, contenido_id TEXT REFERENCES contenidos(id), referencia TEXT NOT NULL, tipo TEXT NOT NULL, numero TEXT, fuente TEXT, texto TEXT NOT NULL, figura TEXT NOT NULL, motivo_sin_clasificar TEXT, ubicacion TEXT NOT NULL);
CREATE TABLE problema_pda(problema_id TEXT NOT NULL REFERENCES problemas(id), pda_id TEXT NOT NULL REFERENCES pdas(id), nivel TEXT NOT NULL CHECK(nivel IN ('Prioritaria','Temática')), evidencia TEXT NOT NULL, metodo TEXT NOT NULL, PRIMARY KEY(problema_id,pda_id));
CREATE TABLE metadatos(clave TEXT PRIMARY KEY, valor TEXT NOT NULL);

CREATE INDEX idx_pda_grado ON pdas(grado,contenido_id);
CREATE INDEX idx_problemas_contenido ON problemas(contenido_id);
CREATE INDEX idx_relacion_pda ON problema_pda(pda_id,nivel);
CREATE VIEW v_cobertura_pda AS SELECT a.id AS pda_id,a.grado,a.pda,c.contenido,COUNT(r.problema_id) AS sugerencias, SUM(CASE WHEN r.nivel='Prioritaria' THEN 1 ELSE 0 END) AS prioritarias FROM pdas a JOIN contenidos c ON c.id=a.contenido_id LEFT JOIN problema_pda r ON r.pda_id=a.id GROUP BY a.id;
CREATE VIEW v_contexto_por_pda AS SELECT a.id AS pda_id,a.grado,a.pda,c.contenido,p.id AS problema_id,p.referencia,p.fuente,p.texto,p.figura,COALESCE(r.nivel,'Solo contenido original') AS nivel,r.evidencia,r.metodo FROM pdas a JOIN contenidos c ON c.id=a.contenido_id JOIN problemas p ON p.contenido_id=c.id LEFT JOIN problema_pda r ON r.pda_id=a.id AND r.problema_id=p.id;
CREATE VIEW v_problemas_por_pda AS SELECT a.id AS pda_id,a.grado,a.pda,c.contenido,p.id AS problema_id,p.referencia,p.fuente,p.texto,p.figura,r.nivel,r.evidencia,r.metodo FROM problema_pda r JOIN pdas a ON a.id=r.pda_id JOIN contenidos c ON c.id=a.contenido_id JOIN problemas p ON p.id=r.problema_id;
COMMIT;
